arguments.new_string:
        if errs:
            # TODO: due to the usage of basic path (not a Path
            # object), the format can be a bit inconsistent here
            # (e.g., 'a.b' and ['a', 'b'])
            raise CheckError(errs, self, scope[Path])
        return ret


class Auto(object):
    """Auto specifier that automatically determines how to handle
    different target types. This is useful when you want glom to
    intelligently process data without needing to specify exactly
    how each type should be handled.

    Args:
       spec: The specification to apply to the target

    >>> target = {'a': {'b': 'c'}}
    >>> glom(target, Auto('a.b'))
    'c'
    """
    def __init__(self, spec=T):
        self.spec = spec

    def glomit(self, target, scope):
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.spec)


class ROOT(object):
    """ROOT is a special specifier that refers to the root/target
    value at the beginning of the glom operation. This is useful
    when you need access to the original input data from within
    a nested specification.

    >>> target = {'a': {'b': 'c'}}
    >>> glom(target, ('a', {'root': ROOT, 'value': 'b'}))
    {'root': {'a': {'b': 'c'}}, 'value': 'c'}
    """
    def glomit(self, target, scope):
        # Return the root target stored in scope
        return scope.get('_ROOT', target)

    def __repr__(self):
        return 'ROOT()'


class Let(object):
    """Let specifier allows capturing intermediate values in a spec
    under named variables that can be referenced later in the same
    specification.

    Args:
       assignments: A dict mapping variable names to their values/specs
       spec: The final specification to evaluate with the captured variables available in scope

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let({'x': 'a', 'y': 'b'}, T['x'] + T['y']))
    3
    """
    def __init__(self, assignments, spec):
        self.assignments = assignments
        self.spec = spec

    def glomit(self, target, scope):
        new_scope = dict(scope)
        for name, val_spec in self.assignments.items():
            new_scope[name] = scope[glom](target, val_spec, scope)
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %r)' % (cn, self.assignments, self.spec)


class Iter(object):
    """Iter specifier iterates over the target and applies a subspec
    to each item, returning a list of results. Similar to a list
    comprehension but using glom's expression syntax.

    Args:
       spec: The specification to apply to each item during iteration

    >>> target = [1, 2, 3, 4, 5]
    >>> glom(target, Iter(T * 2))
    [2, 4, 6, 8, 10]
    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        result = []
        for item in target:
            try:
                result.append(scope[glom](item, self.spec, scope))
            except GlomError:
                pass
        return result

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.spec)


class Fill(object):
    """Fill specifier provides a way to fill in missing or None values
    with a specified default value. Unlike Coalesce which tries multiple
    specs in sequence, Fill simply checks if the result is missing/None
    and replaces it.

    Args:
       spec: The specification to evaluate
       default: Value to use if spec returns None or is missing

    >>> target = {'a': None}
    >>> glom(target, Fill('a', default='missing'))
    'missing'
    """
    def __init__(self, spec, default=None):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        result = scope[glom](target, self.spec, scope)
        if result is None:
            return self.default
        return result

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, default=%r)' % (cn, self.spec, self.default)


class Invoke(object):
    """Invoke specifier calls a function/method with arguments. It
    provides a clean interface for invoking callables with both
    positional and keyword arguments.

    Args:
       func: The callable to invoke
       args: Positional arguments (can be specs or literals)
       kwargs: Keyword arguments (can be specs or literals)
       constants: Values that should not be evaluated as specs (defaults to ())

    >>> class MyClass:
    ...     def greet(self, name):
    ...         return f"Hello {name}"
    >>> obj = MyClass()
    >>> glom(obj, Invoke('greet', 'world'))
    'Hello world'
    """
    def __init__(self, func, args=None, kwargs=None):
        self.func = func
        self.args = args if args is not None else ()
        self.kwargs = kwargs if kwargs is not None else {}
        # Expose constants attribute (not consts) for public API
        self.constants = set()

    def glomit(self, target, scope):
        def _eval(val):
            if type(val) in (Spec, TType) or (isinstance(val, str) and val not in self.constants):
                return scope[glom](target, val, scope)
            return val

        # Evaluate args
        if type(self.args) is tuple:
            eval_args = tuple(_eval(a) for a in self.args)
        else:
            eval_args = _eval(self.args)

        # Evaluate kwargs
        eval_kwargs = {}
        for k, v in self.kwargs.items():
            eval_kwargs[k] = _eval(v)

        # Get the actual callable
        func_val = _eval(self.func)

        return func_val(*eval_args, **eval_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        args_repr = ', '.join([repr(a) for a in self.args]) if self.args else ''
        kwargs_repr = ', '.join(['%s=%r' % (k, v) for k, v in self.kwargs.items()]) if self.kwargs else ''
        parts = [repr(self.func)]
        if args_repr:
            parts.append(args_repr)
        if kwargs_repr:
            parts.append(kwargs_repr)
        return '%s(%s)' % (cn, ', '.join(parts))


